"""
    -> Calculate the factorial of a integer number.
    :parameter number: Number to be calculate.
    :parameter show: (optional) Show the calculation process.
    :return: Factorial of number.
    """
def factorial(number: Any, show: Any = False) -> object {
    num = count=1;
    print(('-' * 40));
    while (count <= number) {
        num *= count;
        if (show == True) {
            print(f'{count}', end='');
            if (count < number) {
                print(end=' x ');
            } elif (count == number) {
                print(end=' = ');
            }
        }
        count += 1;
    }
    return num;
}
